From bfbf28496cd125b497c0edb61c11ed88624e581f Mon Sep 17 00:00:00 2001
From: Marco Martin <notmart@gmail.com>
Date: Mon, 7 Sep 2026 11:31:50 +0200
Subject: [PATCH 1/2] KHintSettings Do not create a KIconLoader in
 KHintSettings ctor

We have a circular dependency here: KIconTheme needs KHintSettings
to correctly know which is the correct fallback theme, but it
was creating a KIconLoader in its own constructor, which in turn created
the KIconTheme for the app, before we had a khintsettings with the proper
fallback theme set.

KHintSettings Qt5: same change as qt6 one
---
 qt5/src/platformtheme/khintssettings.cpp | 5 ++---
 qt6/src/platformtheme/khintssettings.cpp | 5 ++---
 2 files changed, 4 insertions(+), 6 deletions(-)

diff --git a/qt5/src/platformtheme/khintssettings.cpp b/qt5/src/platformtheme/khintssettings.cpp
index 48905f6..0e3c565 100644
--- a/qt5/src/platformtheme/khintssettings.cpp
+++ b/qt5/src/platformtheme/khintssettings.cpp
@@ -82,13 +82,11 @@ KHintsSettings::KHintsSettings(const KSharedConfig::Ptr &kdeglobals)
     KConfigGroup cgToolbar(mKdeGlobals, "Toolbar style");
     m_hints[QPlatformTheme::ToolButtonStyle] = toolButtonStyle(cgToolbar);

-    m_hints[QPlatformTheme::ToolBarIconSize] = KIconLoader::global()->currentSize(KIconLoader::MainToolbar);
-
     m_hints[QPlatformTheme::ItemViewActivateItemOnSingleClick] = readConfigValue(cg, QStringLiteral("SingleClick"), false);

     m_hints[QPlatformTheme::SystemIconThemeName] = readConfigValue(QStringLiteral("Icons"), QStringLiteral("Theme"), QStringLiteral("breeze"));

-    m_hints[QPlatformTheme::SystemIconFallbackThemeName] = QStringLiteral("hicolor");
+    m_hints[QPlatformTheme::SystemIconFallbackThemeName] = QStringLiteral("breeze");
     m_hints[QPlatformTheme::IconThemeSearchPaths] = xdgIconThemePaths();

     QStringList styleNames{
@@ -200,6 +198,7 @@ void KHintsSettings::delayedDBusConnects()

 void KHintsSettings::setupIconLoader()
 {
+    m_hints[QPlatformTheme::ToolBarIconSize] = KIconLoader::global()->currentSize(KIconLoader::MainToolbar);
     connect(KIconLoader::global(), &KIconLoader::iconChanged, this, &KHintsSettings::iconChanged);
 }

diff --git a/qt6/src/platformtheme/khintssettings.cpp b/qt6/src/platformtheme/khintssettings.cpp
index 988ebae..f01017b 100644
--- a/qt6/src/platformtheme/khintssettings.cpp
+++ b/qt6/src/platformtheme/khintssettings.cpp
@@ -85,13 +85,11 @@ KHintsSettings::KHintsSettings(const KSharedConfig::Ptr &kdeglobals)
     KConfigGroup cgToolbar(mKdeGlobals, "Toolbar style");
     m_hints[QPlatformTheme::ToolButtonStyle] = toolButtonStyle(cgToolbar);

-    m_hints[QPlatformTheme::ToolBarIconSize] = KIconLoader::global()->currentSize(KIconLoader::MainToolbar);
-
     m_hints[QPlatformTheme::ItemViewActivateItemOnSingleClick] = readConfigValue(cg, QStringLiteral("SingleClick"), false);

     m_hints[QPlatformTheme::SystemIconThemeName] = readConfigValue(QStringLiteral("Icons"), QStringLiteral("Theme"), QStringLiteral("breeze"));

-    m_hints[QPlatformTheme::SystemIconFallbackThemeName] = QStringLiteral("hicolor");
+    m_hints[QPlatformTheme::SystemIconFallbackThemeName] = QStringLiteral("breeze");
     m_hints[QPlatformTheme::IconThemeSearchPaths] = xdgIconThemePaths();

     QStringList styleNames{
@@ -208,6 +206,7 @@ void KHintsSettings::delayedDBusConnects()

 void KHintsSettings::setupIconLoader()
 {
+    m_hints[QPlatformTheme::ToolBarIconSize] = KIconLoader::global()->currentSize(KIconLoader::MainToolbar);
     connect(KIconLoader::global(), &KIconLoader::iconChanged, this, &KHintsSettings::iconChanged);
 }

